  "privProviders": "Dostawcy usług i przekazywanie danych za granicę",
  "privRetention": "Przechowywanie i usuwanie",
  "privRights": "Twoje prawa",
  "noticeReopen": "Informacja o pamięci",
  "noticeLabel": "Informacja o pamięci przeglądarki",
  "noticeText": "Cook używa pamięci przeglądarki do funkcji gotowania i logowania, z których korzystasz. Nie dodaje się pamięci reklamowej ani analitycznej.",
  "noticeClose": "Zamknij informację o pamięci",
  "privDraftLabel": "Wersja robocza — zaktualizowano 28 października 2026 r.",
  "privDraft": "Funkcje konta są obecnie testowane. Poniższe dane operatora i usług muszą zostać uzupełnione przed publicznym uruchomieniem.",
  "privWho1": "Operatorem Cook jest [pełna nazwa i adres pocztowy operatora]. W sprawach prywatności pisz na [adres e-mail ds. prywatności]. Te dane muszą zostać uzupełnione przed otwarciem rejestracji.",
  "privWhat1": "Gdy tworzysz konto, używamy Twojego adresu e-mail, identyfikatora konta, danych uwierzytelniania hasłem i statusu weryfikacji, aby udostępniać i chronić Twoje konto. Hasła są przetwarzane przez dostawcę uwierzytelniania jako bezpieczne skróty; Cook nie przechowuje czytelnych haseł. Zapisujemy układ kuchni, wybrany język, motyw i jednostki miary, aby przywracać Twoje ustawienia na wszystkich urządzeniach. Do założenia konta potrzebne są e-mail i hasło; przepisy możesz przeglądać bez konta.",
  "privWhat2": "Przetwarzanie danych konta i ustawień jest niezbędne do świadczenia usługi konta, o którą prosisz (art. 6 ust. 1 lit. b RODO). Ograniczone dane dotyczące bezpieczeństwa i zapobiegania nadużyciom mogą być przetwarzane na podstawie prawnie uzasadnionego interesu (art. 6 ust. 1 lit. f), w zakresie niezbędnym i po dokonaniu oceny interesów. E-maile weryfikacyjne i dotyczące resetowania hasła to wiadomości serwisowe, a nie marketing. Funkcja konta nie dodaje reklam ani analityki.",
  "privStorage1": "Cook używa sessionStorage, aby przenosić Twoją kuchnię, postęp gotowania i wybory między stronami w tej samej karcie. Gdy jesteś zalogowany, przechowuje też Twoją sesję uwierzytelniania. Przeglądarka zwykle czyści te dane po zakończeniu sesji karty, ale przywracanie sesji przeglądarki może je zachować. Wylogowanie czyści dane karty Cook. Zamknięcie informacji o pamięci jest zapamiętywane tylko w tej karcie. Własne skrypty Cook nie ustawiają plików cookie. Twoi dostawcy hostingu lub usług mogą prowadzić własne przetwarzanie związane z bezpieczeństwem, które musi zostać udokumentowane przed uruchomieniem.",
  "privStorage2": "OK i przycisk zamknięcia informacji o pamięci jedynie zamykają informację. Nie zezwalają na analitykę, reklamy ani inne opcjonalne śledzenie. Każde przyszłe nieniezbędne przechowywanie będzie wymagało osobnego wyboru przed rozpoczęciem, z równie łatwą odmową i wycofaniem.",
  "privOther1": "Obecna funkcja głosowa listy przepisów pyta country.is o przybliżony kraj na podstawie Twojego adresu IP, aby wybrać język rozpoznawania mowy. Jeśli używasz rozpoznawania przez mikrofon, przeglądarka może wysyłać dźwięk do swojego dostawcy rozpoznawania mowy. Możesz też wpisać składniki. Ci dostawcy, ich zasady i podstawa prawna tych funkcji muszą zostać sprawdzone przed publicznym uruchomieniem.",
  "privProviders1": "Planowany dostawca kont: Supabase (zarządzany PostgreSQL i uwierzytelnianie) z wybranym regionem bazy danych w UE. Dostawca poczty e-mail: [dostawca]. Hosting strony: [dostawca]. Operator musi potwierdzić faktycznych dostawców, umowy powierzenia przetwarzania, podprocesorów, lokalizacje logów oraz wszelkie przekazywanie danych poza EOG. Region bazy danych w UE sam w sobie nie wyklucza przekazywania danych za granicę. W stosownych przypadkach należy wskazać obowiązującą decyzję stwierdzającą odpowiedni stopień ochrony lub zabezpieczenia umowne oraz sposób uzyskania ich kopii.",
  "privRetention1": "Ustawienia konta są przechowywane, dopóki Twoje konto jest aktywne. Możesz poprosić o usunięcie za pośrednictwem podanego wyżej kontaktu ds. prywatności. Przed uruchomieniem operator musi określić sposób obsługi wniosków o usunięcie, termin wygasania niezweryfikowanych kont oraz okresy przechowywania logów bezpieczeństwa i kopii zapasowych. Usunięte dane mogą pozostawać w kopiach zapasowych o ograniczonym dostępie do końca udokumentowanego okresu przechowywania.",
  "privRights1": "W zależności od obowiązujących warunków możesz żądać dostępu, sprostowania, usunięcia, ograniczenia lub przenoszenia danych albo wnieść sprzeciw wobec przetwarzania opartego na prawnie uzasadnionym interesie. Skontaktuj się z operatorem wskazanym wyżej; odpowiedź zwykle następuje w ciągu miesiąca, a każde zgodne z prawem przedłużenie jest wyjaśniane. Możesz złożyć skargę do organu nadzorczego, w tym do węgierskiego NAIH na naih.hu. Cook nie używa ustawień konta do zautomatyzowanych decyzji wywołujących skutki prawne lub podobnie istotne skutki.",
